targets.query:
from(bucket: "ana-lab")
  |> range(start: -5m)
  |> filter(fn: (r) =>
    r._measurement == "net_ifstate"
  )
  |> filter(fn: (r) =>
    r.device != "R5"
  )
  |> filter(fn: (r) =>
    r.device =~ /^${device:regex}$/
  )
  |> filter(fn: (r) =>
    r.interface =~ /^${interface:regex}$/
  )
  |> filter(fn: (r) =>
    r._field == "admin_status" or
    r._field == "oper_status"
  )
  |> group(columns: [
    "device",
    "interface",
    "_field"
  ])
  |> last()
  |> group()
  |> pivot(
    rowKey: ["device", "interface"],
    columnKey: ["_field"],
    valueColumn: "_value"
  )
  |> reduce(
    identity: {interfaces: 0},
    fn: (r, accumulator) => ({
      interfaces: accumulator.interfaces + 1
    })
  )

from(bucket: "ana-lab")
  |> range(start: -5m)
  |> filter(fn: (r) =>
    r._measurement == "net_ifstate"
  )
  |> filter(fn: (r) =>
    r.device != "R5"
  )
  |> filter(fn: (r) =>
    r.device =~ /^${device:regex}$/
  )
  |> filter(fn: (r) =>
    r.interface =~ /^${interface:regex}$/
  )
  |> filter(fn: (r) =>
    r._field == "oper_status"
  )
  |> group(columns: [
    "device",
    "interface"
  ])
  |> last()
  |> group()
  |> reduce(
    identity: {interfaces_up: 0},
    fn: (r, accumulator) => ({
      interfaces_up:
        accumulator.interfaces_up +
        (if r._value == "UP" then 1 else 0)
    })
  )

from(bucket: "ana-lab")
  |> range(
    start: v.timeRangeStart,
    stop: v.timeRangeStop
  )
  |> filter(fn: (r) =>
    r._measurement == "net_ifcounters"
  )
  |> filter(fn: (r) =>
    r.device != "R5"
  )
  |> filter(fn: (r) =>
    r.device =~ /^${device:regex}$/
  )
  |> filter(fn: (r) =>
    r.interface =~ /^${interface:regex}$/
  )
  |> filter(fn: (r) =>
    r._field == "in_octets" or
    r._field == "out_octets"
  )
  |> group(columns: [
    "device",
    "interface",
    "_field"
  ])
  |> aggregateWindow(
    every: v.windowPeriod,
    fn: last,
    createEmpty: false
  )
  |> derivative(
    unit: 1s,
    nonNegative: true
  )
  |> map(fn: (r) => ({
    _time: r._time,
    _value: float(v: r._value) * 8.0,
    _field:
      r.device + " " +
      r.interface + " " +
      (if r._field == "in_octets"
       then "RX"
       else "TX")
  }))
  |> group(columns: ["_field"])

